CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE public.contacts ADD COLUMN IF NOT EXISTS current_request jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS marketing_opt_in boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS last_marketing_at timestamptz;
CREATE TABLE public.estate_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE, label text NOT NULL, kind text NOT NULL DEFAULT 'database', database_source_id uuid REFERENCES public.data_sources(id) ON DELETE CASCADE, endpoint text, field_map jsonb NOT NULL DEFAULT '{}'::jsonb, enabled boolean NOT NULL DEFAULT true, cursor_offset integer NOT NULL DEFAULT 0, sync_started_at timestamptz, last_synced_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.estate_sources TO authenticated; GRANT ALL ON public.estate_sources TO service_role;
ALTER TABLE public.estate_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY estate_sources_owner ON public.estate_sources FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid()));
CREATE TABLE public.estate_properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE, source_id uuid NOT NULL REFERENCES public.estate_sources(id) ON DELETE CASCADE, external_id text NOT NULL, title text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'rent', area text NOT NULL DEFAULT '', price numeric, currency text NOT NULL DEFAULT '', rooms integer, furnished boolean, description text NOT NULL DEFAULT '', photos jsonb NOT NULL DEFAULT '[]'::jsonb, videos jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'available', raw jsonb NOT NULL DEFAULT '{}'::jsonb, first_seen_at timestamptz NOT NULL DEFAULT now(), seen_at timestamptz NOT NULL DEFAULT now(), changed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id, external_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.estate_properties TO authenticated; GRANT ALL ON public.estate_properties TO service_role;
ALTER TABLE public.estate_properties ENABLE ROW LEVEL SECURITY;
CREATE POLICY estate_properties_owner ON public.estate_properties FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.estate_sources s JOIN public.agents a ON a.id = s.agent_id WHERE s.id = source_id AND s.agent_id = estate_properties.agent_id AND a.user_id = auth.uid()));
CREATE TABLE public.estate_stays (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.estate_properties(id) ON DELETE CASCADE, customer_phone text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'confirmed', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT estate_stay_dates CHECK (ends_at > starts_at), CONSTRAINT estate_stay_overlap EXCLUDE USING gist (property_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&) WHERE (status = 'confirmed'));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.estate_stays TO authenticated; GRANT ALL ON public.estate_stays TO service_role;
ALTER TABLE public.estate_stays ENABLE ROW LEVEL SECURITY;
CREATE POLICY estate_stays_owner ON public.estate_stays FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.estate_properties p JOIN public.agents a ON a.id = p.agent_id WHERE p.id = property_id AND p.agent_id = estate_stays.agent_id AND a.user_id = auth.uid()));
CREATE TABLE public.estate_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE, customer_phone text NOT NULL, kind text NOT NULL, property_ref text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.estate_events TO authenticated; GRANT ALL ON public.estate_events TO service_role;
ALTER TABLE public.estate_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY estate_events_owner ON public.estate_events FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid()));
CREATE INDEX estate_events_agent_date ON public.estate_events(agent_id, created_at);
CREATE TABLE public.estate_archives (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE, month text NOT NULL, snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, finalized boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(agent_id, month));
GRANT SELECT, INSERT, UPDATE ON public.estate_archives TO authenticated; GRANT ALL ON public.estate_archives TO service_role;
ALTER TABLE public.estate_archives ENABLE ROW LEVEL SECURITY;
CREATE POLICY estate_archives_read ON public.estate_archives FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid()));
CREATE TABLE public.estate_jobs (agent_id uuid PRIMARY KEY REFERENCES public.agents(id) ON DELETE CASCADE, lease_until timestamptz, last_run_at timestamptz, last_error text);
GRANT SELECT ON public.estate_jobs TO authenticated; GRANT ALL ON public.estate_jobs TO service_role;
ALTER TABLE public.estate_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY estate_jobs_read ON public.estate_jobs FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid()));
CREATE TABLE public.estate_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE, customer_phone text NOT NULL, property_id uuid NOT NULL REFERENCES public.estate_properties(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'reserved', error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(agent_id, customer_phone, property_id));
GRANT SELECT ON public.estate_deliveries TO authenticated; GRANT ALL ON public.estate_deliveries TO service_role;
ALTER TABLE public.estate_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY estate_deliveries_read ON public.estate_deliveries FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = agent_id AND a.user_id = auth.uid()));
CREATE OR REPLACE FUNCTION public.estate_capture_request() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.agent_id IS NOT NULL AND NEW.current_request <> '{}'::jsonb AND (TG_OP = 'INSERT' OR NEW.current_request IS DISTINCT FROM OLD.current_request) THEN INSERT INTO public.estate_events(agent_id, customer_phone, kind, payload) VALUES (NEW.agent_id, NEW.phone, 'request', jsonb_build_object('request', NEW.current_request, 'previous', CASE WHEN TG_OP = 'UPDATE' THEN OLD.current_request ELSE '{}'::jsonb END)); END IF; RETURN NEW; END $$;
CREATE TRIGGER estate_request_history AFTER INSERT OR UPDATE OF current_request ON public.contacts FOR EACH ROW EXECUTE FUNCTION public.estate_capture_request();
CREATE OR REPLACE FUNCTION public.estate_acquire_lease(p_agent uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed uuid; BEGIN INSERT INTO public.estate_jobs(agent_id, lease_until, last_run_at) VALUES(p_agent, now()+interval '10 minutes',now()) ON CONFLICT(agent_id) DO UPDATE SET lease_until=EXCLUDED.lease_until, last_run_at=now() WHERE estate_jobs.lease_until IS NULL OR estate_jobs.lease_until < now() RETURNING agent_id INTO claimed; RETURN claimed IS NOT NULL; END $$;
REVOKE ALL ON FUNCTION public.estate_acquire_lease(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.estate_acquire_lease(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.estate_reserve_marketing(p_agent uuid,p_phone text,p_property uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE delivery uuid; BEGIN UPDATE public.contacts SET last_marketing_at=now() WHERE agent_id=p_agent AND phone=p_phone AND marketing_opt_in AND lead_status<>'closed' AND (last_marketing_at IS NULL OR last_marketing_at <= now()-interval '48 hours'); IF NOT FOUND THEN RETURN NULL; END IF; INSERT INTO public.estate_deliveries(agent_id,customer_phone,property_id) VALUES(p_agent,p_phone,p_property) ON CONFLICT DO NOTHING RETURNING id INTO delivery; IF delivery IS NULL THEN RAISE EXCEPTION 'offer already reserved'; END IF; RETURN delivery; END $$;
REVOKE ALL ON FUNCTION public.estate_reserve_marketing(uuid,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.estate_reserve_marketing(uuid,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.estate_validate_stay() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.estate_properties WHERE id=NEW.property_id AND agent_id=NEW.agent_id AND category='hotel') THEN RAISE EXCEPTION 'property must be a hotel listing for this assistant'; END IF; RETURN NEW; END $$;
CREATE TRIGGER estate_stay_agent BEFORE INSERT OR UPDATE ON public.estate_stays FOR EACH ROW EXECUTE FUNCTION public.estate_validate_stay();